// Explicit definitions use slot geometry, not identity hashes or arbitrary hue.
export const GAP_C_MOTIFS=Object.fromEntries(Object.entries(REVIEWED).map(([slug,row])=>{
 const roots={cast:'',hit:'',aura:'',area:'',bolt:''};
 for(const node of row.nodes)if(node.asset){
  if(roots[node.slot]&&roots[node.slot]!==node.asset)throw Error(`Mixed artwork in ${slug}/${node.slot}`);
  roots[node.slot]=node.asset;
 }
 const hasFan=row.nodes.some(n=>n.type==='fan');
 const firstLocal=row.nodes.find(n=>n.asset&&n.type==='body')?.asset??'glint';
 for(const slot of ['cast','hit','aura'])roots[slot] ||= firstLocal;
 roots.bolt ||= ART.link;
 roots.area ||= hasFan?'detect_magic.cone':firstLocal;
 return [`gapC-${slug}`,{label:row.label,pattern:row.pattern??(hasFan?'coneObjectFan':row.areaLayout==='tiles'?'lineTiles':`gapC-${slug}`),...roots,
  symbolic:row.symbolic,castingOnly:row.castingOnly,
  ...(row.nativeArea?{nativeArea:true}:{}),theme:row.theme,
  ...(row.delivery?{delivery:row.delivery}:{}),...(row.previewArea?{previewArea:row.previewArea}:{}),
  ...(row.areaLayout?{areaLayout:row.areaLayout}:{})}];
}));
export const GAP_C_DESIGNS=Object.fromEntries(Object.keys(REVIEWED).map(slug=>[slug,[`gapC-${slug}`,'']]));

export function gapCLayers(spell,{fx,copy,pose,track,subject}){
 const slug=spell.design?.motif?.replace(/^gapC-/,'');
 const row=REVIEWED[slug];
 if(!row)return null;
 // A projectile fan alone does not show the native cone; add its footprint.
 const nodes=row.nodes.some(n=>n.type==='fan')&&!row.nodes.some(n=>n.slot==='area')&&spell.delivery==='cone'
  ?[...row.nodes,A('area','detect_magic.cone','Cone footprint',{opacity:.4,delay:0,fadeOut:300})]:row.nodes;
 return nodes.map((node,index)=>{
  const extra={...node.options};
  const delay=extra.delay??index*450;
  delete extra.delay;
  const duration=Math.max(4500,(spell.design.mediaTiming?.[node.slot]?.duration??0)/(extra.playbackRate??1));
  if(extra.tween){extra.tracks=extra.tween.map(([property,from,to,span])=>track(property,from,to,span));delete extra.tween;}
  if(node.type==='copy')return copy(node.label,delay,4500,{...extra});
  if(node.type==='pose'){
   const {duration=1600,distance=.25,intensity=.35,...motion}=extra;
   return {...pose(node.motion,node.label,delay,duration,node.subject,distance,intensity),...motion};
  }
  if(node.type==='travel')return fx('travel','bolt',node.label,delay,duration,{scale:.6,fadeIn:150,fadeOut:450,...extra});
  if(node.type==='fan')return fx('projectile','bolt',node.label,delay,duration,{travelDestination:'area',areaLayout:'fan',fanCount:5,scale:.45,fadeIn:0,fadeOut:400,...extra});
  if(node.type==='area')return fx('template',node.slot,node.label,delay,duration,{scale:1,below:true,opacity:.9,fadeIn:400,fadeOut:700,areaLayout:row.areaLayout??'fit',...extra});
  const who=extra.subject??subject;
  const kind=who==='targets'?'impact':'cast';
  return fx(kind,node.slot,node.label,delay,duration,{kind,subject:who,scale:1,fadeIn:300,fadeOut:650,...extra});
 });
}
